function imageBlock(src,alt,cls=''){return src.endsWith('.mp4')?`<video class="${cls}" controls playsinline preload="metadata" poster="./public/assets/videos/thai-roots-poster.jpg"><source src="./public/${src}" type="video/mp4"></video>`:`<img class="${cls}" src="${assetPath(src)}" alt="${alt}" loading="lazy">`}
function renderPr(){const p=prPlan[lang];document.getElementById('roadmap-grid').innerHTML=p.roadmap.map(([title,body],i)=>`<article class="roadmap-card paired-card"><figure>${imageBlock(prVisuals.roadmap[i],title,(i===3||i===4||i===5)?'contain-visual':'')}</figure><div><span>0${i+1}</span><h4>${title}</h4><p>${body}</p></div></article>`).join('');document.getElementById('roadmap-deck').innerHTML=roadmapDeck[lang].map((card,i)=>`<article class="roadmap-detail-card paired-detail"><figure>${imageBlock(prVisuals.detail[i],card.title,i===3?'contain-visual':'')}</figure><div class="paired-detail-copy"><div><span>${card.tag}</span><h4>${card.title}</h4></div>${card.groups.map(([title,items])=>`<section><h5>${title}</h5><ul>${items.map(item=>`<li>${item}</li>`).join('')}</ul></section>`).join('')}</div></article>`).join('');document.getElementById('audience-grid').innerHTML=p.audience.map(([title,body],i)=>`<article class="audience-card paired-card"><figure>${imageBlock(prVisuals.audience[i],title,i===2?'contain-visual':'')}</figure><div><b>0${i+1}</b><h4>${title}</h4><p>${body}</p></div></article>`).join('');document.getElementById('nation-points').innerHTML=p.nation.map(([title,body],i)=>`<article class="paired-nation"><figure>${imageBlock(prVisuals.nation[i],title,(i===1||i===2)?'contain-visual':'')}</figure><b>0${i+1}</b><div><h4>${title}</h4><p>${body}</p></div></article>`).join('');document.getElementById('press-grid').innerHTML=pressData[lang].map((item,i)=>`<article class="press-card paired-press"><figure>${imageBlock(prVisuals.press[i],item.title,i===0?'press-proof-image':'contain-visual')}</figure><div><span>0${i+1} / ${item.source}</span><time>${item.date}</time><h4>${item.title}</h4><p>${item.body}</p>${item.url?`<a href="${item.url}" target="_blank" rel="noreferrer">READ SOURCE ↗</a>`:''}</div></article>`).join('');const r=riderData[lang];document.getElementById('rider-details').innerHTML=`<div class="rider-meta"><span>${r.engineer}</span></div><div class="rider-columns"><article><h4>STAGE POSITIONS</h4><ul>${r.band.map(x=>`<li>${x}</li>`).join('')}</ul></article><article><h4>MIXER LINE</h4><ul class="input-list">${r.inputs.map(x=>`<li>${x}</li>`).join('')}</ul></article></div><div class="rider-columns rider-equipment"><article><h4>${r.providedTitle}</h4><ul>${r.provided.map(x=>`<li>${x}</li>`).join('')}</ul></article><article><h4>${r.venueTitle}</h4><ul>${r.venue.map(x=>`<li>${x}</li>`).join('')}</ul></article></div><p class="rider-note">${r.note}</p>`}
function renderPressVisual(){}
function renderAnalytics(){const max=Math.max(...streamingData.map(d=>d.total));document.getElementById('song-chart').innerHTML=streamingData.map(d=>`<div class="song-row"><div class="song-meta"><span>${d.name}</span><b>${d.total.toLocaleString()}</b></div><div class="bar-track"><div class="bar-total" style="width:${(d.total/max*100).toFixed(1)}%"><i class="yt" style="width:${(d.yt/d.total*100).toFixed(1)}%"></i><i class="sp" style="width:${(d.sp/d.total*100).toFixed(1)}%"></i><i class="am" style="width:${(d.am/d.total*100).toFixed(1)}%"></i></div></div></div>`).join('');document.getElementById('audience-legend').innerHTML=audienceLabels[lang].map(([name,value],i)=>`<div><i class="aud-${i}"></i><span>${name}</span><b>${value}%</b></div>`).join('')}
function openRecord(i){const [title,body]=records[lang][i];const modal=document.getElementById('record-modal');modal.querySelector('.modal-index').textContent=`0${i+1} / DEADKAT DISCOGRAPHY`;modal.querySelector('h3').textContent=title;modal.querySelector('.modal-body').textContent=body;modal.showModal()}
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{lang=b.dataset.lang;localStorage.setItem('deadkat-lang',lang);render()}));
document.querySelector('.menu-toggle').addEventListener('click',e=>{const nav=document.querySelector('.nav');nav.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',nav.classList.contains('open'))});
document.querySelectorAll('.nav a').forEach(a=>a.addEventListener('click',()=>document.querySelector('.nav').classList.remove('open')));
document.querySelector('.modal-close').addEventListener('click',()=>document.getElementById('record-modal').close());
document.getElementById('year').textContent=new Date().getFullYear();render();
